import os, re

def main():
    d = os.environ["INPUT"]
    pat = re.compile(r'^(\S+) \S+ \S+ \[[^\]]*\] "([^"]*)" (\d{3}) (\d+|-)$')
    status = {}
    total = 0
    paths = {}
    errs = {}
    with open(os.path.join(d, "access.log"), encoding="utf-8", errors="replace") as f:
        for line in f:
            line = line.rstrip("\r\n")
            m = pat.match(line)
            if not m:
                continue
            ip, req, st, size = m.groups()
            parts = req.split()
            if len(parts) < 2:
                continue
            path = parts[1].split("?", 1)[0]
            status[st] = status.get(st, 0) + 1
            total += 0 if size == "-" else int(size)
            paths[path] = paths.get(path, 0) + 1
            if st.startswith("5"):
                errs[ip] = errs.get(ip, 0) + 1
    out = []
    for st in sorted(status, key=int):
        out.append(f"{st} {status[st]}")
    out.append(f"bytes {total}")
    if paths:
        best = min(paths.items(), key=lambda kv: (-kv[1], kv[0]))
        out.append(f"top {best[0]} {best[1]}")
    for ip, c in sorted(errs.items(), key=lambda kv: (-kv[1], kv[0])):
        out.append(f"errors {ip} {c}")
    print("\n".join(out))

main()

import os
import re

ROMAN_RE = re.compile(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$')
VALS = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'),
        (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
SYM = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}


def to_roman(n):
    out = []
    for v, s in VALS:
        while n >= v:
            out.append(s)
            n -= v
    return ''.join(out)


def from_roman(s):
    total = 0
    for i, ch in enumerate(s):
        v = SYM[ch]
        if i + 1 < len(s) and SYM[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total


def convert(s):
    if s.isascii() and s.isdigit():
        n = int(s)
        if 1 <= n <= 3999:
            return to_roman(n)
        return "invalid"
    if s and ROMAN_RE.match(s):
        return str(from_roman(s))
    return "invalid"


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "numbers.txt"), encoding="utf-8", errors="replace") as f:
        data = f.read()
    for line in data.splitlines():
        s = line.strip()
        if not s:
            continue
        print(f"{s} = {convert(s)}")


