import os

def check(line):
    pairs = {')': '(', ']': '[', '}': '{'}
    closer = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in closer:
            stack.append(ch)
        elif ch in pairs:
            if not stack:
                return "col %d: unexpected %s" % (i, ch)
            if stack[-1] != pairs[ch]:
                return "col %d: expected %s, found %s" % (i, closer[stack[-1]], ch)
            stack.pop()
    if stack:
        return "unclosed " + closer[stack[-1]]
    return "ok"

