import os, re
from collections import defaultdict

def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "timings.log"), "rb") as f:
        data = f.read().decode("utf-8", "surrogateescape")
    groups = defaultdict(list)
    pat = re.compile(r"^[+-]?[0-9]+$")
    for line in data.split("\n"):
        parts = line.split()
        if len(parts) != 3:
            continue
        m, p, t = parts
        if not pat.match(t):
            continue
        groups[(m, p)].append(int(t))
    def key(k):
        return (k[0].encode("utf-8", "surrogateescape"), k[1].encode("utf-8", "surrogateescape"))
    out = []
    for k in sorted(groups, key=key):
        t = sorted(groups[k])
        n = len(t)
        def pc(P):
            return t[(P * n + 99) // 100 - 1]
        line = "%s %s count=%d p50=%d p95=%d max=%d" % (k[0], k[1], n, pc(50), pc(95), t[-1])
        out.append(line)
    if out:
        print("\n".join(out))

main()

