def main():
    d = os.environ["INPUT"]
    groups = {}
    pat = re.compile(r"-?[0-9]+\Z", re.ASCII)
    with open(os.path.join(d, "timings.log"), "r", encoding="utf-8", errors="surrogateescape", newline="") as f:
        data = f.read()
    for line in data.split("\n"):
        line = line.rstrip("\r")
        parts = line.split()
        if len(parts) != 3:
            continue
        m, p, ms = parts
        if not pat.match(ms):
            continue
        groups.setdefault((m, p), []).append(int(ms))
    def key(k):
        return (k[0].encode("utf-8", "surrogateescape"), k[1].encode("utf-8", "surrogateescape"))
    out = []
    for k in sorted(groups, key=key):
        t = sorted(groups[k])
        n = len(t)
        def pr(P):
            return t[max(1, -(-P * n // 100)) - 1]
        out.append("%s %s count=%d p50=%d p95=%d max=%d" % (k[0], k[1], n, pr(50), pr(95), t[-1]))
    if out:
        print("\n".join(out))

