import os, heapq

def main():
    d = os.environ["INPUT"]
    adj = {}
    trips = []
    with open(os.path.join(d, "routes.txt"), encoding="utf-8", errors="surrogateescape") as f:
        for line in f:
            s = line.strip()
            if not s or s.startswith("#"):
                continue
            p = s.split()
            if p[0] == "road" and len(p) >= 4:
                a, b, c = p[1], p[2], int(p[3])
                adj.setdefault(a, []).append((b, c))
                adj.setdefault(b, []).append((a, c))
            elif p[0] == "trip" and len(p) >= 3:
                trips.append((p[1], p[2]))

    def key(n):
        return n.encode("utf-8", "surrogateescape")

    cache = {}

    def dijkstra(src):
        if src in cache:
            return cache[src]
        dist = {src: 0}
        pq = [(0, src)]
        while pq:
            du, u = heapq.heappop(pq)
            if du > dist.get(u, float("inf")):
                continue
            for v, w in adj.get(u, ()):
                nd = du + w
                if nd < dist.get(v, float("inf")):
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        cache[src] = dist
        return dist

    out = []
    for x, y in trips:
        if x == y:
            out.append("%s 0" % x)
            continue
        dist = dijkstra(y)
        if x not in dist:
            out.append("%s %s unreachable" % (x, y))
            continue
        path = [x]
        u = x
        while u != y:
            best = None
            for v, w in adj[u]:
                if v in dist and w + dist[v] == dist[u]:
                    if best is None or key(v) < key(best):
                        best = v
            u = best
            path.append(u)
        out.append("%s %d" % (" -> ".join(path), dist[x]))
    print("\n".join(out))

