import json
import os


def merge(base, over):
    result = dict(base)
    for k, v in over.items():
        if v is None:
            result.pop(k, None)
        elif isinstance(v, dict):
            b = result.get(k)
            result[k] = merge(b if isinstance(b, dict) else {}, v)
        else:
            result[k] = v
    return result


def leaves(v, path, out):
    if isinstance(v, dict):
        if not v:
            out.append((path, "{}"))
        else:
            for k, x in v.items():
                leaves(x, path + "." + k if path else k, out)
    elif isinstance(v, list):
        if not v:
            out.append((path, "[]"))
        else:
            for i, x in enumerate(v):
                leaves(x, path + "." + str(i) if path else str(i), out)
    else:
        out.append((path, json.dumps(v)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), encoding="utf-8") as f:
        over = json.load(f)
    merged = merge(base, over)
    out = []
    leaves(merged, "", out)
    out.sort(key=lambda t: t[0].encode("utf-8"))
    for p, v in out:
        print(p + "=" + v)


main()

import json
import os


def strip(v):
    if isinstance(v, dict):
        return {k: strip(x) for k, x in v.items() if x is not None}
    return v


def merge(b, o):
    r = dict(b)
    for k, v in o.items():
        if v is None:
            r.pop(k, None)
        elif isinstance(v, dict) and isinstance(r.get(k), dict):
            r[k] = merge(r[k], v)
        else:
            r[k] = strip(v)
    return r


def leaves(v, p, out):
    if isinstance(v, dict):
        if not v and p:
            out.append((p, "{}"))
        for k, x in v.items():
            leaves(x, p + "." + k if p else k, out)
    elif isinstance(v, list):
        if not v and p:
            out.append((p, "[]"))
        for i, x in enumerate(v):
            leaves(x, p + "." + str(i) if p else str(i), out)
    else:
        out.append((p, json.dumps(v)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), encoding="utf-8") as f:
        ov = json.load(f)
    m = merge(base, ov)
    out = []
    leaves(m, "", out)
    out.sort(key=lambda t: t[0].encode("utf-8"))
    for p, v in out:
        print(p + "=" + v)


main()

