                  errors="surrogateescape", newline="") as f:
            for l in items:
                f.write(l + "\n")

    print("error %d" % len(buckets["error"]))
    print("warn %d" % len(buckets["warn"]))
    print("info %d" % len(buckets["info"]))
    print("other %d" % other)


