import os
import json


def main():
    input_dir = os.environ["INPUT"]
    counts_path = os.environ["COUNTS"]

    counts = {}
    if os.path.exists(counts_path):
        try:
            with open(counts_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                counts = {str(k): int(v) for k, v in data.items()}
        except (ValueError, OSError):
            counts = {}

    visits = os.path.join(input_dir, "visits.txt")
    if os.path.isfile(visits):
        with open(visits, "r", encoding="utf-8", errors="surrogateescape") as f:
            for line in f:
                page = line.strip()
                if not page:
                    continue
                counts[page] = counts.get(page, 0) + 1

    payload = json.dumps(counts)
    tmp = counts_path + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, counts_path)
    except OSError:
        with open(counts_path, "w", encoding="utf-8") as f:
            f.write(payload)

    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0].encode("utf-8", "surrogateescape")))
    out = []
    for page, total in items:
        out.append("%s %d" % (page, total))
    if out:
        sys_out = "\n".join(out) + "\n"
        os.write(1, sys_out.encode("utf-8", "surrogateescape"))


main()

