import sys
import json


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    counts = {}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = f.read()
            if data.strip():
                loaded = json.loads(data)
                if isinstance(loaded, dict):
                    counts = {str(k): int(v) for k, v in loaded.items()}
        except (ValueError, OSError):
            counts = {}

    visits_path = os.path.join(input_dir, "visits.txt")
    try:
        with open(visits_path, "r", encoding="utf-8", errors="surrogateescape") as f:
            for line in f:
                page = line.strip()
                if not page:
                    continue
                counts[page] = counts.get(page, 0) + 1
    except FileNotFoundError:
        pass

    with open(kv_path, "w", encoding="utf-8") as f:
        json.dump(counts, f)

    def key(item):
        page, total = item
        return (-total, page.encode("utf-8", "surrogateescape"))

    out = sys.stdout.buffer
    for page, total in sorted(counts.items(), key=key):
        out.write(page.encode("utf-8", "surrogateescape") + b" " + str(total).encode() + b"\n")
    out.flush()


