        if cmd == "put" and len(args) == 3:
            users[args[0]] = {"name": args[1], "email": args[2]}
            out.append("ok " + args[0])
        elif cmd == "rename" and len(args) == 2:
            if args[0] in users:
                users[args[0]]["name"] = args[1]
