            else:
                out.append("missing " + args[0])
        elif cmd == "get" and len(args) == 1:
            u = users.get(args[0])
            if u is None:
                out.append("missing " + args[0])
            else:
                out.append(json.dumps(
                    {"id": args[0], "name": u["name"], "email": u["email"]},
                    separators=(",", ":"), ensure_ascii=False))
        elif cmd == "del" and len(args) == 1:
            if args[0] in users:
                del users[args[0]]
                out.append("ok " + args[0])
            else:
                out.append("missing " + args[0])
        elif cmd == "count" and len(args) == 0:
            out.append("count %d" % len(users))
        else:
            out.append("bad " + line)

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(users, f)
    os.replace(tmp, kv_path)

    if out:
        sys_out = "\n".join(out) + "\n"
        import sys
        sys.stdout.write(sys_out)


