import os
import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

KV_PATH = os.environ.get("COUNTS")
LOCK = threading.Lock()
DATA = {}

if KV_PATH and os.path.exists(KV_PATH):
    try:
        with open(KV_PATH, "r") as f:
            loaded = json.load(f)
        if isinstance(loaded, dict):
            DATA = {str(k): int(v) for k, v in loaded.items()}
    except Exception:
        DATA = {}

ALLOWED = set("abcdefghijklmnopqrstuvwxyz0123456789-")


def valid(name):
    return 1 <= len(name) <= 32 and all(c in ALLOWED for c in name)


def save():
    if not KV_PATH:
        return
    with open(KV_PATH, "w") as f:
        json.dump(DATA, f)
        f.flush()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj):
        body = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        if n > 0:
            self.rfile.read(n)
        m = self.command
        p = self.path
        if m == "POST" and p.startswith("/hit/"):
            name = p[5:]
            if not valid(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                DATA[name] = DATA.get(name, 0) + 1
                c = DATA[name]
                save()
            return self.send_json(200, {"name": name, "count": c})
        if m == "GET" and p.startswith("/count/"):
            name = p[7:]
            if not valid(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                c = DATA.get(name, 0)
            return self.send_json(200, {"name": name, "count": c})
        if m == "GET" and p == "/top":
            with LOCK:
                items = sorted(DATA.items(), key=lambda kv: (-kv[1], kv[0].encode()))[:3]
            return self.send_json(200, [{"name": k, "count": v} for k, v in items])
        return self.send_json(404, {"error": "not found"})

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


def main():
    port = int(os.environ["PORT"])
    srv = ThreadingHTTPServer(("127.0.0.1", port), H)
    srv.daemon_threads = True
    srv.serve_forever()


