import os, json, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

PATH = os.environ.get("STORE", "store.json")
LOCK = threading.Lock()


def load():
    try:
        with open(PATH, "r") as f:
            d = json.load(f)
        if isinstance(d, dict) and "todos" in d and "next" in d:
            return d
    except Exception:
        pass
    return {"next": 1, "todos": []}


def save(d):
    tmp = PATH + ".tmp"
    try:
        with open(tmp, "w") as f:
            json.dump(d, f)
        os.replace(tmp, PATH)
    except Exception:
        with open(PATH, "w") as f:
            json.dump(d, f)


def valid_title(t):
    return isinstance(t, str) and t.strip() != ""


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        if obj is None:
            self.send_response(code)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(b)

    def body(self):
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def nf(self):
        self.send(404, {"error": "not found"})

    def handle_any(self):
        raw = self.body()
        u = urlsplit(self.path)
        parts = u.path.split("/")
        m = self.command
        if len(parts) == 2 and parts[1] == "todos" or (len(parts) == 3 and parts[1] == "todos" and parts[2] == "" and False):
            coll = True
        else:
            coll = False
        if coll:
            if m == "POST":
                try:
                    j = json.loads(raw.decode("utf-8"))
                except Exception:
                    j = None
                if not isinstance(j, dict) or not valid_title(j.get("title")):
                    return self.send(400, {"error": "title required"})
                with LOCK:
                    d = load()
                    t = {"id": d["next"], "title": j["title"].strip(), "done": False}
                    d["next"] += 1
                    d["todos"].append(t)
                    save(d)
                return self.send(201, t)
            if m == "GET":
                q = parse_qs(u.query).get("done")
                with LOCK:
                    d = load()
                ts = sorted(d["todos"], key=lambda t: t["id"])
                if q:
                    if q[-1] == "true":
                        ts = [t for t in ts if t["done"]]
                    elif q[-1] == "false":
                        ts = [t for t in ts if not t["done"]]
                return self.send(200, ts)
            return self.nf()
        if len(parts) == 3 and parts[1] == "todos" and m in ("GET", "PATCH", "DELETE"):
            s = parts[2]
            if not (s.isascii() and s.isdigit() and str(int(s)) == s):
                return self.nf()
            i = int(s)
            with LOCK:
                d = load()
                t = next((x for x in d["todos"] if x["id"] == i), None)
                if t is None:
                    return self.nf()
                if m == "GET":
                    return self.send(200, t)
                if m == "DELETE":
                    d["todos"] = [x for x in d["todos"] if x["id"] != i]
                    save(d)
                    return self.send(204)
                try:
                    j = json.loads(raw.decode("utf-8"))
                except Exception:
                    j = None
                ok = isinstance(j, dict)
                if ok and "title" in j and not valid_title(j["title"]):
                    ok = False
                if ok and "done" in j and not isinstance(j["done"], bool):
                    ok = False
                if not ok:
                    return self.send(400, {"error": "bad update"})
                if "title" in j:
                    t["title"] = j["title"].strip()
                if "done" in j:
                    t["done"] = j["done"]
                save(d)
                return self.send(200, t)
        return self.nf()

    do_GET = do_POST = do_PATCH = do_DELETE = do_PUT = do_HEAD = do_OPTIONS = handle_any


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    ThreadingHTTPServer(("127.0.0.1", port), H).serve_forever()

import os, re, json, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

conn = sqlite3.connect(os.environ["DB"], check_same_thread=False, isolation_level=None)
conn.execute("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)")
lock = threading.Lock()
ID_RE = re.compile(r"/notes/([0-9]+)", re.ASCII)


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        data = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def nf(self):
        self.send(404, {"error": "not found"})

    def handle_any(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        m = self.command
        u = urlsplit(self.path)
        path = u.path
        if m == "POST" and path == "/notes":
            return self.create(raw)
        if m == "GET" and path == "/notes":
            return self.listing(u.query)
        mm = ID_RE.fullmatch(path)
        if mm and m in ("GET", "DELETE"):
            nid = int(mm.group(1))
            with lock:
                row = conn.execute("SELECT id,title,body,tags FROM notes WHERE id=?", (nid,)).fetchone()
                if row is None:
                    return self.nf()
                if m == "DELETE":
                    conn.execute("DELETE FROM notes WHERE id=?", (nid,))
                    return self.send(200, {"deleted": nid})
            return self.send(200, {"id": row[0], "title": row[1], "body": row[2], "tags": json.loads(row[3])})
        self.nf()

    def create(self, raw):
        bad = lambda: self.send(400, {"error": "invalid note"})
        try:
            d = json.loads(raw.decode())
        except Exception:
            return bad()
        if not isinstance(d, dict):
            return bad()
        t, b = d.get("title"), d.get("body")
        tags = d.get("tags", [])
        if not isinstance(t, str) or not t or not isinstance(b, str):
            return bad()
        if not isinstance(tags, list) or not all(isinstance(x, str) for x in tags):
            return bad()
        out = []
        for x in tags:
            x = x.lower()
            if x not in out:
                out.append(x)
        with lock:
            cur = conn.execute("INSERT INTO notes(title,body,tags) VALUES(?,?,?)", (t, b, json.dumps(out)))
            nid = cur.lastrowid
        self.send(201, {"id": nid})

    def listing(self, query):
        qs = parse_qs(query)
        tag = qs.get("tag", [None])[0]
        q = qs.get("q", [None])[0]
        if tag:
            tag = tag.lower()
        with lock:
            rows = conn.execute("SELECT id,title,body,tags FROM notes ORDER BY id DESC").fetchall()
        out = []
        for i, t, b, tg in rows:
            if tag and tag not in json.loads(tg):
                continue
            if q and q not in t and q not in b:
                continue
            out.append({"id": i, "title": t})
        self.send(200, out)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H).serve_forever()

