    stations = get("/stations").get("stations", [])
    stations = sorted(stations, key=lambda s: s["name"].encode("utf-8"))
    for s in stations:
        name = s["name"]
        try:
            data = get("/stations/%s/readings" % urllib.parse.quote(str(s["id"]), safe=""))
            temps = [
