import os, json, sys

def main():
    d = os.environ.get("INPUT", "")
    try:
        with open(os.path.join(d, "packages.json"), "rb") as f:
            data = json.loads(f.read().decode("utf-8"))
    except Exception:
        print("error: not an object")
        return
    if not isinstance(data, dict):
        print("error: not an object")
        return
    sys.setrecursionlimit(100000)
    valid = {}
    invalid = []
    for k, v in data.items():
        if isinstance(v, list) and all(isinstance(x, str) for x in v):
            valid[k] = sorted(set(v))
        else:
            invalid.append(k)
    out = []
    # stages via fixed point
    stage = {}
    changed = True
    while changed:
        changed = False
        for p, deps in valid.items():
            if p in stage:
                continue
            if all(x in stage for x in deps):
                stage[p] = 1 + max((stage[x] for x in deps), default=0)
                changed = True
    by = {}
    for p, s in stage.items():
        by.setdefault(s, []).append(p)
    for s in sorted(by):
        out.append("stage %d: %s" % (s, ", ".join(sorted(by[s]))))
    # SCC (Tarjan)
    index = {}
    low = {}
    onst = set()
    st = []
    sccs = []
    counter = [0]

    def sc(v):
        index[v] = low[v] = counter[0]
        counter[0] += 1
        st.append(v)
        onst.add(v)
        for w in valid[v]:
            if w not in valid:
                continue
            if w not in index:
                sc(w)
                low[v] = min(low[v], low[w])
            elif w in onst:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            comp = []
            while True:
                w = st.pop()
                onst.discard(w)
                comp.append(w)
                if w == v:
                    break
            sccs.append(comp)

    for p in sorted(valid):
        if p not in index:
            sc(p)
    incycle = set()
    groups = []
    for c in sccs:
        if len(c) >= 2 or (c[0] in valid[c[0]]):
            groups.append(sorted(c))
            incycle.update(c)
    groups.sort(key=lambda g: g[0])
    for g in groups:
        out.append("cycle: " + ", ".join(g))
    miss = {}
    for p, deps in valid.items():
        for x in deps:
            if x not in valid:
                miss.setdefault(x, []).append(p)
    for m in sorted(miss):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(miss[m]))))
    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid)))
    blocked = sorted(p for p in valid if p not in stage and p not in incycle)
    if blocked:
        out.append("blocked: " + ", ".join(blocked))
    out.append("built %d of %d" % (len(stage), len(valid)))
    print("\n".join(out))

main()

import os, re, sys

def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "bookings.csv"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")
    lines = text.split("\n")
    pat = re.compile(r"^([0-9]{2}):([0-9]{2})$", re.A)

    def parse(s, allow24):
        m = pat.match(s)
        if not m:
            return None
        h, mi = int(m.group(1)), int(m.group(2))
        if mi > 59:
            return None
        if h > 23:
            if allow24 and h == 24 and mi == 0:
                return 1440
            return None
        return h * 60 + mi

    def fmt(m):
        return "%02d:%02d" % (m // 60, m % 60)

    seen = set()
    skipped = []
    data = {}
    for i, line in enumerate(lines):
        n = i + 1
        if n == 1:
            continue
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        parts = line.split(",")
        if len(parts) != 5:
            skipped.append(n)
            continue
        s = parse(parts[2], False)
        e = parse(parts[3], True)
        if s is None or e is None or e <= s:
            skipped.append(n)
            continue
        key = tuple(parts)
        if key in seen:
            continue
        seen.add(key)
        data.setdefault(parts[0], {}).setdefault(parts[1], []).append((s, e, parts[4]))

    out = []
    bk = lambda x: x.encode("utf-8", "surrogateescape")
    for room in sorted(data, key=bk):
        for day in sorted(data[room], key=bk):
            bs = data[room][day]
            out.append("%s %s" % (room, day))
            merged = []
            for s, e, _ in sorted(bs):
                if merged and s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
            out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))
            free = []
            cur = 540
            for s, e in merged:
                if e <= 540:
                    continue
                if s >= 1080:
                    break
                if s - cur >= 30 and s > cur:
                    free.append((cur, min(s, 1080)))
                cur = max(cur, e)
            if cur < 1080 and 1080 - cur >= 30:
                free.append((cur, 1080))
            if free:
