import sys


def parse_time(s, is_end):
    if len(s) != 5 or s[2] != ":":
        return None
    digits = "0123456789"
    if not all(c in digits for c in s[:2] + s[3:]):
        return None
    h = int(s[:2])
    m = int(s[3:])
    if m > 59:
        return None
    if h == 24 and m == 0 and is_end:
        return 1440
    if h > 23:
        return None
    return h * 60 + m


def fmt(m):
    return "%02d:%02d" % (m // 60, m % 60)


def main():
    base = os.environ["INPUT"]
