        seen.add(key)
        data.setdefault(room, {}).setdefault(day, []).append((s, e, who))

    out = []
    for room in sorted(data):
        for day in sorted(data[room]):
            bk = data[room][day]
            out.append("%s %s" % (room, day))
            merged = []
            for s, e, _ in sorted(bk):
                if merged and s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
            out.append("  busy " + ", ".join("%s-%s" % (fmt(a), fmt(b)) for a, b in merged))
            free = []
