import os, json, sys

class F(float):
    pass

def bad_const(s):
    raise ValueError(s)

def is_int(v):
    return type(v) is int

def is_num(v):
    return (type(v) is int) or isinstance(v, float)

def validate(v, s, path, errs):
    t = s.get("type")
    if t == "object":
        if not isinstance(v, dict):
            errs.append((path, "expected object")); return
        props = s.get("properties", {})
        for r in s.get("required", []):
            if r not in v:
                errs.append((path + "." + r, "missing required field"))
        for k, val in v.items():
            if k in props:
                validate(val, props[k], path + "." + k, errs)
            elif s.get("additional", True) is False:
                errs.append((path + "." + k, "unexpected field"))
    elif t == "array":
        if not isinstance(v, list):
            errs.append((path, "expected array")); return
        if "min_items" in s and len(v) < s["min_items"]:
            errs.append((path, "fewer than %d items" % s["min_items"]))
        if "items" in s:
            for i, e in enumerate(v):
                validate(e, s["items"], "%s[%d]" % (path, i), errs)
    elif t == "string":
        if not isinstance(v, str):
            errs.append((path, "expected string")); return
        if "min_length" in s and len(v) < s["min_length"]:
            errs.append((path, "shorter than %d" % s["min_length"]))
        elif "max_length" in s and len(v) > s["max_length"]:
            errs.append((path, "longer than %d" % s["max_length"]))
        elif "enum" in s and v not in s["enum"]:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        ok = is_int(v) if t == "integer" else is_num(v)
        if not ok:
            errs.append((path, "expected " + t)); return
        if "minimum" in s and v < s["minimum"]:
            errs.append((path, "less than %d" % s["minimum"]))
        elif "maximum" in s and v > s["maximum"]:
            errs.append((path, "greater than %d" % s["maximum"]))
    elif t == "boolean":
        if not isinstance(v, bool):
            errs.append((path, "expected boolean"))
    elif t == "null":
        if v is not None:
            errs.append((path, "expected null"))

def main():
