    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()
    out = []
    total = valid = 0
    key = lambda e: (e[0].encode("utf-8", "surrogatepass"), e[1].encode("utf-8", "surrogatepass"))
    for n, raw in enumerate(lines, 1):
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            text = None
        if text is not None and text.strip() == "":
            continue
        total += 1
        try:
            if text is None:
                raise ValueError
            rec = json.loads(text, parse_float=F, parse_constant=bad_const)
        except (ValueError, RecursionError):
            out.append("line %d: invalid JSON" % n)
            continue
        errs = []
        validate(rec, schema, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % n)
        else:
            for p, m in sorted(errs, key=key):
                out.append("line %d: %s: %s" % (n, p, m))
