import os, sys, json, urllib.request, urllib.error, urllib.parse


def main():
    inp = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")
    key = os.environ.get("API_KEY", "")

    state = {}
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            s = json.load(f)
        if isinstance(s, dict):
            state = {k: v for k, v in s.items() if isinstance(v, int)}
    except Exception:
        state = {}

    def save():
        tmp = state_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(state, f)
        os.replace(tmp, state_path)

    with open(os.path.join(inp, "records.jsonl"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")

    out = []
    records = {}
    for n, line in enumerate(text.split("\n"), 1):
        line = line.rstrip("\r")
        if line.strip() == "":
            continue
        try:
            obj = json.loads(line)
        except Exception:
            obj = None
        if (not isinstance(obj, dict) or not isinstance(obj.get("id"), str)
                or not isinstance(obj.get("version"), int)
                or isinstance(obj.get("version"), bool)):
            out.append("line %d invalid" % n)
            continue
        records[obj["id"]] = obj

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    def attempt(rec):
        url = api + "/records/" + urllib.parse.quote(rec["id"], safe="")
        body = json.dumps(rec, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(url, data=body, method="PUT", headers={
            "content-type": "application/json",
            "Authorization": "Bearer " + key,
        })
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status
        except urllib.error.HTTPError as e:
            return e.code
        except Exception:
            return None

    for rid in sorted(records, key=lambda s: s.encode("utf-8", "surrogatepass")):
        rec = records[rid]
        last = state.get(rid)
        if last is not None and rec["version"] <= last:
            out.append("%s unchanged" % rid)
            counts["unchanged"] += 1
            continue
        result = "failed"
        for _ in range(3):
            st = attempt(rec)
            if st is not None and 200 <= st < 300:
                state[rid] = rec["version"]
                save()
                result = "synced"
                break
            if st is not None and 400 <= st < 500:
                result = "rejected %d" % st
                break
        counts[result.split()[0]] += 1
        out.append("%s %s" % (rid, result))

    out.append("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))
    sys.stdout.write("\n".join(out) + "\n")


