import os, re, sqlite3, sys
from datetime import datetime, timezone

MAXV = 9223372036854775807
INT = re.compile(r'[+-]?[0-9]+\Z')


def fmt(ms):
    return datetime.fromtimestamp(ms // 1000, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')


def main():
    inp = os.environ['INPUT']
    dbp = os.environ['DB']
    logp = os.environ['LOG']
    now = int(os.environ['CLOCK'])
    ts = fmt(now)
    with open(os.path.join(inp, 'ops.txt'), 'rb') as f:
        text = f.read().decode('utf-8', 'replace')
    db = sqlite3.connect(dbp)
    db.execute('create table if not exists accounts(name text primary key, balance integer not null, last integer not null, closed integer not null default 0)')
    db.execute('create table if not exists transfers(id text primary key, frm text not null, "to" text not null, cents integer not null)')
    db.commit()
    ok = failed = dup = 0
    logs = []

    def bal(name):
        r = db.execute('select balance from accounts where name=? and closed=0', (name,)).fetchone()
        return None if r is None else r[0]

    for n, line in enumerate(text.split('\n'), 1):
        line = line.rstrip('\r')
        if line.strip() == '':
            continue
        w = line.split(' ')
        err = None
        op = w[0]
        if op == 'open' and len(w) == 3 and INT.match(w[2]):
            name = w[1]
            c = int(w[2])
            if c < 0 or c > MAXV:
                err = 'bad amount'
            elif db.execute('select 1 from accounts where name=?', (name,)).fetchone():
                err = 'account exists'
            else:
                db.execute('insert into accounts values(?,?,?,0)', (name, c, now))
        elif op == 'close' and len(w) == 2:
            b = bal(w[1])
            if b is None:
                err = 'no account ' + w[1]
            elif b != 0:
                err = 'balance not zero'
            else:
                db.execute('update accounts set closed=1, last=? where name=?', (now, w[1]))
        elif op == 'transfer' and len(w) == 5 and INT.match(w[4]):
            tid, a, b, c = w[1], w[2], w[3], int(w[4])
            prev = db.execute('select frm,"to",cents from transfers where id=?', (tid,)).fetchone()
            if prev is not None:
                if prev == (a, b, c):
                    dup += 1
                    continue
                err = 'id reused'
            elif c <= 0:
                err = 'bad amount'
            elif a == b:
                err = 'same account'
            else:
                ba = bal(a)
                bb = bal(b)
                if ba is None:
                    err = 'no account ' + a
                elif bb is None:
                    err = 'no account ' + b
                elif ba < c:
                    err = 'insufficient funds'
                elif bb + c > MAXV:
                    err = 'overflow'
                else:
                    db.execute('update accounts set balance=?, last=? where name=?', (ba - c, now, a))
                    db.execute('update accounts set balance=?, last=? where name=?', (bb + c, now, b))
                    db.execute('insert into transfers values(?,?,?,?)', (tid, a, b, c))
        else:
            err = 'malformed'
        if err:
            failed += 1
            logs.append('%s line %d: %s\n' % (ts, n, err))
        else:
            ok += 1
    db.commit()
    if logs:
        with open(logp, 'a', encoding='utf-8') as f:
            f.write(''.join(logs))
    rows = db.execute('select name,balance,last from accounts where closed=0').fetchall()
    rows.sort(key=lambda r: r[0].encode('utf-8', 'surrogatepass'))
    out = ['ok %d failed %d duplicate %d' % (ok, failed, dup)]
    for name, b, l in rows:
        out.append('%s %d last %s' % (name, b, fmt(l)))
    sys.stdout.buffer.write(('\n'.join(out) + '\n').encode('utf-8', 'replace'))
    db.close()


main()

