        if t < u["locked_until"]:
            return self.send(429, {"error": "locked"})
        try:
            h = hpw(u["salt"], p)
        except Exception:
            h = ""
        if not secrets.compare_digest(h, u["hash"]):
            u["fails"] += 1
            if u["fails"] >= 3:
                u["fails"] = 0
                u["locked_until"] = t + 900000
            save(d)
            return self.send(*bad)
        u["fails"] = 0
        u["logins"] += 1
        tok = secrets.token_bytes(16).hex()
        d["sessions"][tok] = {"name": n, "expires": t + 1800000}
        save(d)
        self.send(200, {"token": tok, "expires_in": 1800})

