        tok = self.token()
        d = load()
        s = d["sessions"].get(tok) if tok else None
        t = now()
        if not s or t >= s["expires"] or s["name"] not in d["users"]:
            return self.send(401, {"error": "unauthorized"})
        s["expires"] = t + 1800000
        save(d)
        self.send(200, {"name": s["name"], "logins": d["users"][s["name"]]["logins"]})

    def logout(self):
        tok = self.token()
        d = load()
        s = d["sessions"].get(tok) if tok else None
        if not s or now() >= s["expires"]:
            return self.send(401, {"error": "unauthorized"})
        del d["sessions"][tok]
        save(d)
        self.send(204)


