import os, json, re, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

LOCK = threading.Lock()
DB = sqlite3.connect(os.environ["DB"], check_same_thread=False)
DB.executescript("""
CREATE TABLE IF NOT EXISTS payments(
 n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL,
 currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idem(
 key TEXT PRIMARY KEY, method TEXT, path TEXT, body TEXT, status INTEGER, resp TEXT);
""")
DB.commit()

ID_RE = re.compile(r"^pay_([1-9][0-9]*)$")


def pay(row):
    return {"id": "pay_%d" % row[0], "account": row[1], "cents": row[2],
            "currency": row[3], "status": row[4], "refunded": row[5]}


def getrow(n):
    return DB.execute("SELECT n,account,cents,currency,status,refunded FROM payments WHERE n=?", (n,)).fetchone()


def isint(v):
    return isinstance(v, int) and not isinstance(v, bool)


def canon(raw):
    try:
        return json.dumps(json.loads(raw.decode("utf-8")), sort_keys=True), True
    except Exception:
        return "INVALID:" + raw.hex(), False


def handle(method, rawpath, headers, raw):
    parts = urlsplit(rawpath)
    path = parts.path
    segs = [s for s in path.split("/")]
    NF = (404, {"error": "not found"})
    if method == "GET":
        if path == "/payments":
            q = parse_qs(parts.query)
            acc = q.get("account", [None])[0]
            if acc is None:
                return 200, []
            rows = DB.execute("SELECT n,account,cents,currency,status,refunded FROM payments WHERE account=? ORDER BY n", (acc,)).fetchall()
            return 200, [pay(r) for r in rows]
        if len(segs) == 3 and segs[1] == "payments":
            m = ID_RE.match(segs[2])
            if m:
                r = getrow(int(m.group(1)))
                if r:
                    return 200, pay(r)
        return NF
    if method != "POST":
        return NF
    kind = None
    n = None
    if path == "/payments":
        kind = "create"
    elif len(segs) == 4 and segs[1] == "payments" and segs[3] in ("capture", "cancel", "refund"):
        m = ID_RE.match(segs[2])
        if not m:
            return NF
        n = int(m.group(1))
        kind = segs[3]
    else:
        return NF
    key = None
    cbody, valid = canon(raw)
    if kind in ("create", "refund"):
        key = headers.get("idempotency-key")
        if key is None:
            return 400, {"error": "missing idempotency key"}
        r = DB.execute("SELECT method,path,body,status,resp FROM idem WHERE key=?", (key,)).fetchone()
        if r:
            if r[0] == "POST" and r[1] == path and r[2] == cbody:
                return r[3], json.loads(r[4])
            return 409, {"error": "key reused"}
    body = json.loads(raw.decode("utf-8")) if valid else None
    if kind == "create":
        if not (isinstance(body, dict) and set(body) == {"account", "cents", "currency"}
                and isinstance(body["account"], str) and body["account"]
                and isint(body["cents"]) and body["cents"] > 0
                and body["currency"] in ("EUR", "USD")):
            return 422, {"error": "invalid payment"}
        cur = DB.execute("INSERT INTO payments(account,cents,currency,status,refunded) VALUES(?,?,?,?,0)",
                         (body["account"], body["cents"], body["currency"], "pending"))
        res = (201, pay(getrow(cur.lastrowid)))
    else:
        r = getrow(n)
        if not r:
            return NF
        if kind == "capture":
            if r[4] == "pending":
                DB.execute("UPDATE payments SET status='captured' WHERE n=?", (n,))
            elif r[4] != "captured":
                return 409, {"error": "invalid transition"}
            return 200, pay(getrow(n))
        if kind == "cancel":
            if r[4] != "pending":
                return 409, {"error": "invalid transition"}
            DB.execute("UPDATE payments SET status='canceled' WHERE n=?", (n,))
            return 200, pay(getrow(n))
        # refund
        if not (isinstance(body, dict) and set(body) == {"cents"} and isint(body["cents"]) and body["cents"] > 0):
            return 422, {"error": "invalid refund"}
        if r[4] != "captured":
            return 409, {"error": "invalid transition"}
        tot = r[5] + body["cents"]
        if tot > r[2]:
            return 409, {"error": "exceeds captured"}
        st = "refunded" if tot == r[2] else "captured"
        DB.execute("UPDATE payments SET refunded=?, status=? WHERE n=?", (tot, st, n))
        res = (200, pay(getrow(n)))
    DB.execute("INSERT INTO idem(key,method,path,body,status,resp) VALUES(?,?,?,?,?,?)",
               (key, "POST", path, cbody, res[0], json.dumps(res[1])))
    return res


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def run(self):
        try:
            ln = int(self.headers.get("content-length") or 0)
        except ValueError:
            ln = 0
        raw = self.rfile.read(ln) if ln > 0 else b""
        hd = {k.lower(): v for k, v in self.headers.items()}
        with LOCK:
            try:
                status, obj = handle(self.command, self.path, hd, raw)
                DB.commit()
            except Exception:
                DB.rollback()
                status, obj = 500, {"error": "internal"}
        data = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = run


ThreadingHTTPServer.daemon_threads = True
ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H).serve_forever()

import os, re, json, hashlib, sys

SEP = re.compile(rb'[\x00-\x2f\x3a-\x40\x5b-\x60\x7b-\x7f]+')


def words_of(b):
    out = set()
    for w in SEP.split(b):
        if w:
            out.add(w.decode('utf-8', 'replace').lower())
    return out


def main():
    docs = os.environ['DOCS']
    queries = os.environ['QUERIES']
    kv = os.environ['INDEX']
    old = {}
    try:
        with open(kv, 'r', encoding='utf-8') as f:
            old = json.load(f).get('files', {})
    except Exception:
        old = {}
    cur = {}
    for root, dirs, files in os.walk(docs):
        for fn in files:
            full = os.path.join(root, fn)
            rel = os.path.relpath(full, docs).replace(os.sep, '/')
            try:
                with open(full, 'rb') as f:
                    data = f.read()
            except OSError:
                continue
            h = hashlib.sha256(data).hexdigest()
            o = old.get(rel)
            if o and o.get('hash') == h:
                cur[rel] = o
            else:
                cur[rel] = {'hash': h, 'words': sorted(words_of(data))}
    key = lambda p: p.encode('utf-8', 'surrogateescape')
    out = []
    unchanged = 0
    for p in sorted(set(cur) | set(old), key=key):
        if p not in old:
            out.append('added ' + p)
        elif p not in cur:
            out.append('removed ' + p)
        elif old[p].get('hash') != cur[p]['hash']:
            out.append('changed ' + p)
        else:
            unchanged += 1
    out.append('unchanged %d' % unchanged)

    inv = {}
    for p, e in cur.items():
        for w in e['words']:
            inv.setdefault(w, set()).add(p)

    try:
        with open(os.path.join(queries, 'queries.txt'), 'rb') as f:
            text = f.read().decode('utf-8', 'replace')
    except OSError:
        text = ''
    allp = set(cur)
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        ws = words_of(line.encode('utf-8'))
        res = set(allp)
        for w in ws:
            res &= inv.get(w, set())
        if res:
            out.append('%s: %s' % (line, ', '.join(sorted(res, key=key))))
        else:
            out.append('%s: none' % line)

    with open(kv, 'w', encoding='utf-8') as f:
        json.dump({'files': cur}, f)
    sys.stdout.buffer.write(('\n'.join(out) + '\n').encode('utf-8', 'surrogateescape'))


main()

import os, json

def main():
    inp = os.environ["INPUT"]
    qpath = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])
    jobs = {}
    if os.path.exists(qpath):
        try:
            with open(qpath, encoding="utf-8") as f:
                jobs = json.load(f).get("jobs", {})
        except Exception:
            jobs = {}

    ep = os.path.join(inp, "enqueue.jsonl")
    if os.path.exists(ep):
        with open(ep, encoding="utf-8", errors="replace") as f:
            lines = f.read().split("\n")
        for n, line in enumerate(lines, 1):
            line = line.strip()
            if not line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                o = None
            if (not isinstance(o, dict) or not isinstance(o.get("id"), str)
                    or not isinstance(o.get("priority"), int)
                    or isinstance(o.get("priority"), bool)):
                print("invalid line %d" % n)
                continue
            if o["id"] in jobs:
                print("duplicate ID")
                continue
            jobs[o["id"]] = {"priority": o["priority"], "due": now,
                             "attempts": 0, "state": "pending"}

    script = {}
    sp = os.path.join(inp, "script.json")
    if os.path.exists(sp):
        try:
            with open(sp, encoding="utf-8") as f:
                script = json.load(f)
        except Exception:
            script = {}

    due = [i for i, j in jobs.items() if j["state"] == "pending" and j["due"] <= now]
    due.sort(key=lambda i: (-jobs[i]["priority"], jobs[i]["due"], i.encode("utf-8")))
    for i in due[:5]:
        j = jobs[i]
        j["attempts"] += 1
        a = j["attempts"]
        outs = script.get(i)
        if isinstance(outs, list) and outs:
            out = outs[min(a - 1, len(outs) - 1)]
        else:
            out = "ok"
        if out == "fail":
            if a >= 4:
                j["state"] = "dead"
                print("dead " + i)
            else:
                s = 60 * (2 ** (a - 1))
                j["due"] = now + s * 1000
                print("retry %s in %d" % (i, s))
        else:
            j["state"] = "done"
            print("done " + i)

    c = {"pending": 0, "done": 0, "dead": 0}
    for j in jobs.values():
        c[j["state"]] += 1
    print("pending %d done %d dead %d" % (c["pending"], c["done"], c["dead"]))

    with open(qpath, "w", encoding="utf-8") as f:
        json.dump({"jobs": jobs}, f)

