class Syn(Exception):
    pass


class Err(Exception):
    pass


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in " \t\r\f\v":
            i += 1
        elif c in "0123456789":
            j = i
            while j < n and s[j] in "0123456789":
                j += 1
            toks.append(("int", int(s[i:j])))
            i = j
        elif c == "_" or ("a" <= c <= "z") or ("A" <= c <= "Z"):
            j = i
            while j < n and (s[j] == "_" or s[j] in "0123456789" or "a" <= s[j] <= "z" or "A" <= s[j] <= "Z"):
                j += 1
            toks.append(("name", s[i:j]))
            i = j
        elif c in "+-*/%^(),=":
            toks.append(("op", c))
            i += 1
        else:
            raise Syn()
    return toks


class Parser:
    def __init__(self, toks, pos=0):
        self.t = toks
        self.p = pos

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else (None, None)

    def isop(self, o):
        return self.peek() == ("op", o)

    def expr(self):
        node = self.term()
        while self.isop("+") or self.isop("-"):
            op = self.peek()[1]
            self.p += 1
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.isop("*") or self.isop("/") or self.isop("%"):
            op = self.peek()[1]
            self.p += 1
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.isop("-"):
            self.p += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.isop("^"):
            self.p += 1
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == "int":
            self.p += 1
            return ("int", v)
        if k == "name":
            self.p += 1
            if self.isop("("):
                self.p += 1
                args = [self.expr()]
                while self.isop(","):
                    self.p += 1
                    args.append(self.expr())
                if not self.isop(")"):
                    raise Syn()
                self.p += 1
                return ("call", v, args)
            return ("var", v)
        if k == "op" and v == "(":
            self.p += 1
            e = self.expr()
            if not self.isop(")"):
                raise Syn()
            self.p += 1
            return e
        raise Syn()


def chk(v):
    if v < MIN or v > MAX:
        raise Err("overflow")
    return v


FUNCS = {"min": 2, "max": 2, "abs": 1}


def ev(node, env):
    k = node[0]
    if k == "int":
        return chk(node[1])
    if k == "var":
        if node[1] not in env:
            raise Err("unknown variable " + node[1])
        return env[node[1]]
    if k == "neg":
        return chk(-ev(node[1], env))
    if k == "call":
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise Err("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise Err("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    op = node[1]
    a = ev(node[2], env)
    b = ev(node[3], env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op in "/%":
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == "/":
            return chk(q)
        return chk(a - b * q)
    if b < 0:
        raise Err("negative exponent")
    if abs(a) <= 1:
        return chk(a ** b)
    if b > 64:
        raise Err("overflow")
    return chk(a ** b)


def main():
    d = os.environ.get("INPUT", "input")
    with open(os.path.join(d, "program.txt"), encoding="utf-8", errors="replace") as f:
        lines = f.read().split("\n")
    env = {}
    out = []
    for no, line in enumerate(lines, 1):
        if not line.strip():
            continue
        try:
            toks = tokenize(line)
            if not toks:
                continue
            target = None
            if toks[0] == ("name", "let"):
                if len(toks) < 3 or toks[1][0] != "name" or toks[2] != ("op", "="):
                    raise Syn()
                target = toks[1][1]
                p = Parser(toks, 3)
            else:
                p = Parser(toks, 0)
            tree = p.expr()
            if p.p != len(toks):
                raise Syn()
            v = ev(tree, env)
            if target is not None:
                env[target] = v
                out.append("%d: %s = %d" % (no, target, v))
            else:
                out.append("%d: %d" % (no, v))
        except Syn:
            out.append("%d: error: syntax error" % no)
        except Err as e:
            out.append("%d: error: %s" % (no, e))
    print("\n".join(out))


main()

