MAXV = 9223372036854775807
MINV = -9223372036854775808


class Err(Exception):
    pass


TOK = re.compile(r"\s*(?:(\d+)|([A-Za-z_][A-Za-z0-9_]*)|([-+*/%^(),=]))")


def tokenize(s):
    toks = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = TOK.match(s, pos)
        if not m:
            raise Err("syntax error")
        if m.group(1) is not None:
            toks.append(("int", m.group(1)))
        elif m.group(2) is not None:
            toks.append(("name", m.group(2)))
        else:
            toks.append(("op", m.group(3)))
        pos = m.end()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else (None, None)

    def op(self, o):
        return self.peek() == ("op", o)

    def eat(self, o):
        if not self.op(o):
            raise Err("syntax error")
        self.i += 1

    def expr(self):
        n = self.term()
        while self.op("+") or self.op("-"):
            o = self.peek()[1]
            self.i += 1
            n = ("bin", o, n, self.term())
        return n

    def term(self):
        n = self.factor()
        while self.peek()[0] == "op" and self.peek()[1] in "*/%":
            o = self.peek()[1]
            self.i += 1
            n = ("bin", o, n, self.factor())
        return n

    def factor(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.op("^"):
            self.i += 1
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == "int":
            self.i += 1
            return ("int", int(v))
        if k == "name":
            self.i += 1
            if self.op("("):
                self.i += 1
                args = [self.expr()]
                while self.op(","):
                    self.i += 1
                    args.append(self.expr())
                self.eat(")")
                return ("call", v, args)
            return ("var", v)
        if self.op("("):
            self.i += 1
            n = self.expr()
            self.eat(")")
            return n
        raise Err("syntax error")


def chk(v):
    if v < MINV or v > MAXV:
        raise Err("overflow")
    return v


FUNCS = {"min": 2, "max": 2, "abs": 1}


def ev(n, env):
    k = n[0]
    if k == "int":
        return chk(n[1])
    if k == "var":
        if n[1] not in env:
            raise Err("unknown variable " + n[1])
        return env[n[1]]
    if k == "neg":
        return chk(-ev(n[1], env))
    if k == "call":
        name, args = n[1], n[2]
        if name not in FUNCS:
            raise Err("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise Err("wrong number of arguments to " + name)
        vs = [ev(a, env) for a in args]
        if name == "min":
            return min(vs)
        if name == "max":
            return max(vs)
        return chk(abs(vs[0]))
    o = n[1]
    a = ev(n[2], env)
    b = ev(n[3], env)
    if o == "+":
        return chk(a + b)
    if o == "-":
        return chk(a - b)
    if o == "*":
        return chk(a * b)
    if o in "/%":
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if o == "/":
            return chk(q)
        return chk(a - q * b)
    if b < 0:
        raise Err("negative exponent")
    if a in (0, 1):
        return 1 if b == 0 else a
