import os, sys, re

LO, HI = -2**63, 2**63 - 1

class Err(Exception):
    pass

TOK = re.compile(r'\s*(?:(\d+)|([A-Za-z_][A-Za-z0-9_]*)|([-+*/%^(),=]))')

def tokenize(s):
    toks = []
    pos = 0
    s = s.rstrip()
    while pos < len(s):
        m = TOK.match(s, pos)
        if not m:
            raise Err("syntax error")
        if m.group(1) is not None:
            toks.append(("int", m.group(1)))
        elif m.group(2) is not None:
            toks.append(("name", m.group(2)))
        else:
            toks.append(("op", m.group(3)))
        pos = m.end()
    return toks

class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else (None, None)

    def op(self, o):
        k, v = self.peek()
        return k == "op" and v == o

    def eat(self, o):
        if self.op(o):
            self.i += 1
        else:
            raise Err("syntax error")

    def expr(self):
        n = self.term()
        while self.op("+") or self.op("-"):
            o = self.peek()[1]
            self.i += 1
            n = ("bin", o, n, self.term())
        return n

    def term(self):
        n = self.factor()
        while self.op("*") or self.op("/") or self.op("%"):
            o = self.peek()[1]
            self.i += 1
            n = ("bin", o, n, self.factor())
        return n

    def factor(self):
        if self.op("-"):
            self.i += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.op("^"):
            self.i += 1
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == "int":
            self.i += 1
            return ("int", int(v))
        if k == "name":
            self.i += 1
            if self.op("("):
                self.i += 1
                args = [self.expr()]
                while self.op(","):
                    self.i += 1
                    args.append(self.expr())
                self.eat(")")
                return ("call", v, args)
            return ("var", v)
        if self.op("("):
            self.i += 1
            n = self.expr()
            self.eat(")")
            return n
        raise Err("syntax error")

def chk(v):
    if v < LO or v > HI:
        raise Err("overflow")
    return v

FUNCS = {"min": 2, "max": 2, "abs": 1}

def ev(n, env):
    k = n[0]
    if k == "int":
        return chk(n[1])
    if k == "var":
        if n[1] not in env:
            raise Err("unknown variable " + n[1])
        return env[n[1]]
    if k == "neg":
        return chk(-ev(n[1], env))
    if k == "call":
        name, args = n[1], n[2]
        if name not in FUNCS:
            raise Err("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise Err("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    op = n[1]
    a = ev(n[2], env)
    b = ev(n[3], env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op in "/%":
        if b == 0:
            raise Err("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == "/":
            return chk(q)
        return chk(a - b * q)
    if b < 0:
        raise Err("negative exponent")
    if abs(a) >= 2 and b > 64:
        raise Err("overflow")
    return chk(a ** b)

def run_line(line, env):
    toks = tokenize(line)
    if toks[0] == ("name", "let"):
        if len(toks) < 4 or toks[1][0] != "name" or toks[2] != ("op", "="):
            raise Err("syntax error")
        p = Parser(toks[3:])
        tree = p.expr()
        if p.i != len(p.t):
            raise Err("syntax error")
        v = ev(tree, env)
        env[toks[1][1]] = v
        return "%s = %d" % (toks[1][1], v)
    p = Parser(toks)
    tree = p.expr()
    if p.i != len(p.t):
        raise Err("syntax error")
    return str(ev(tree, env))

def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "program.txt"), encoding="utf-8", errors="replace") as f:
        text = f.read()
    env = {}
    out = []
    for n, line in enumerate(text.split("\n"), 1):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        try:
            out.append("%d: %s" % (n, run_line(line, env)))
        except Err as e:
            out.append("%d: error: %s" % (n, e))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))

main()

import os, sys, json, hmac, hashlib, sqlite3, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, unquote

DB = os.environ["DB"]
SECRETS = os.environ["SECRETS"]
LOG = os.environ["LOG"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()

TYPES = ("subscription.created", "subscription.activated", "payment.failed", "subscription.canceled")
TRANS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}


def connect():
    c = sqlite3.connect(DB, timeout=30, isolation_level=None)
    c.executescript("""
    CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS subs(id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS history(sub TEXT NOT NULL, n INTEGER NOT NULL, state TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS pending(sub TEXT NOT NULL, seq INTEGER NOT NULL, id TEXT NOT NULL, type TEXT NOT NULL, PRIMARY KEY(sub, seq));
    """)
    return c


with LOCK:
    connect().close()


def log(line):
    with open(LOG, "a", encoding="utf-8") as f:
        f.write(line + "\n")


def secret():
    with open(os.path.join(SECRETS, "webhook.key"), "rb") as f:
        d = f.read()
    if d.endswith(b"\n"):
        d = d[:-1]
    return d


def handle_event(ev):
    c = connect()
    try:
        c.execute("BEGIN IMMEDIATE")
        if c.execute("SELECT 1 FROM events WHERE id=?", (ev["id"],)).fetchone():
            c.execute("COMMIT")
            return 200, {"status": "duplicate"}
        c.execute("INSERT INTO events(id) VALUES(?)", (ev["id"],))
        sub, seq = ev["subscription"], ev["seq"]
        row = c.execute("SELECT state, seq FROM subs WHERE id=?", (sub,)).fetchone()
        state, last = row if row else ("none", 0)
        if seq <= last:
            c.execute("COMMIT")
            return 200, {"status": "stale"}
        if seq > last + 1:
            c.execute("INSERT OR IGNORE INTO pending VALUES(?,?,?,?)", (sub, seq, ev["id"], ev["type"]))
            c.execute("COMMIT")
            return 202, {"status": "queued"}
        applied = 0
        cur = (ev["id"], ev["type"])
        nseq = last + 1
        hn = c.execute("SELECT COUNT(*) FROM history WHERE sub=?", (sub,)).fetchone()[0]
        while cur is not None:
            eid, typ = cur
            frm, to = TRANS[typ]
            if state in frm:
                state = to
                c.execute("INSERT INTO history VALUES(?,?,?)", (sub, hn, state))
                hn += 1
            else:
                log("invalid transition " + eid)
            last = nseq
            applied += 1
            nxt = c.execute("SELECT id, type FROM pending WHERE sub=? AND seq=?", (sub, last + 1)).fetchone()
            if nxt:
                c.execute("DELETE FROM pending WHERE sub=? AND seq=?", (sub, last + 1))
                cur = (nxt[0], nxt[1])
                nseq = last + 1
            else:
                cur = None
        c.execute("INSERT OR REPLACE INTO subs VALUES(?,?,?)", (sub, state, last))
        c.execute("COMMIT")
        return 200, {"status": "applied", "applied": applied}
    except BaseException:
        try:
            c.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        c.close()


def get_sub(sid):
    c = connect()
    try:
        row = c.execute("SELECT state, seq FROM subs WHERE id=?", (sid,)).fetchone()
        if not row:
            return 404, {"error": "not found"}
        h = [r[0] for r in c.execute("SELECT state FROM history WHERE sub=? ORDER BY n", (sid,))]
        return 200, {"id": sid, "state": row[0], "seq": row[1], "history": h}
    finally:
        c.close()


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj):
        b = json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        path = urlsplit(self.path).path
        if path.startswith("/subscriptions/") and len(path) > len("/subscriptions/"):
            sid = unquote(path[len("/subscriptions/"):])
            with LOCK:
                code, obj = get_sub(sid)
            return self.send(code, obj)
        self.send(404, {"error": "not found"})

    def do_POST(self):
        n = int(self.headers.get("content-length") or 0)
        body = self.rfile.read(n) if n else b""
        path = urlsplit(self.path).path
        if path != "/webhooks":
            return self.send(404, {"error": "not found"})
        sig = self.headers.get("x-signature")
        exp = "sha256=" + hashlib.sha256(secret() + b"." + body).hexdigest()
        if sig is None or not hmac.compare_digest(sig.encode("utf-8", "replace"), exp.encode()):
            with LOCK:
                log("rejected signature")
            return self.send(401, {"error": "bad signature"})
        try:
            ev = json.loads(body.decode("utf-8"))
        except Exception:
            ev = None
        ok = (isinstance(ev, dict)
              and all(isinstance(ev.get(k), str) for k in ("id", "type", "subscription"))
              and ev["type"] in TYPES
              and isinstance(ev.get("seq"), int) and not isinstance(ev.get("seq"), bool)
              and ev["seq"] >= 1)
        if not ok:
            return self.send(400, {"error": "invalid event"})
        with LOCK:
            code, obj = handle_event(ev)
        self.send(code, obj)

    def do_PUT(self):
        self.send(404, {"error": "not found"})

    do_DELETE = do_PATCH = do_PUT


ThreadingHTTPServer.daemon_threads = True
ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
